// Extract input from webhook body
const { topic, depth, pexelsKey, analyzerProvider, analyzerModel, analyzerKey, writerProvider, writerModel, writerKey, combinerProvider, combinerModel, combinerKey } = $input.first().json.body;

const SECTION_COUNTS = { brief: 4, standard: 7, deep: 11 };
const numSections = SECTION_COUNTS[depth] || 7;

return [{
  json: {
    topic,
    depth,
    numSections,
    pexelsKey: pexelsKey || '',
    analyzer: { provider: analyzerProvider, model: analyzerModel, apiKey: analyzerKey },
    writer: { provider: writerProvider, model: writerModel, apiKey: writerKey },
    combiner: { provider: combinerProvider, model: combinerModel, apiKey: combinerKey }
  }
}];

