// Parse the Analyzer AI response to extract the paper plan
const input = $input.first().json;
const prevData = $('⚙️ Parse Input').first().json;

let rawContent = '';

// Handle OpenAI-compatible format
if (input.choices && input.choices[0]) {
  rawContent = input.choices[0].message.content;
}
// Handle Anthropic format
else if (input.content && input.content[0]) {
  rawContent = input.content[0].text;
}
// Handle Gemini format
else if (input.candidates && input.candidates[0]) {
  rawContent = input.candidates[0].content.parts[0].text;
}

// Extract JSON from the response
let plan;
try {
  const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
  plan = JSON.parse(jsonMatch ? jsonMatch[0] : rawContent);
} catch (e) {
  // Fallback plan
  const titles = ['Introduction', 'Background', 'Methodology', 'Results', 'Analysis', 'Discussion', 'Conclusion'];
  plan = {
    title: `Research Paper: ${prevData.topic}`,
    abstract: `This paper explores ${prevData.topic} in depth.`,
    sections: titles.slice(0, prevData.numSections).map(t => ({
      title: t,
      imageQuery: `${prevData.topic} ${t}`,
      keyPoints: `Detailed exploration of ${t} related to ${prevData.topic}.`
    }))
  };
}

// Output each section as a separate item for the loop
const items = plan.sections.map((section, index) => ({
  json: {
    ...prevData,
    paperTitle: plan.title,
    paperAbstract: plan.abstract,
    allSections: plan.sections,
    currentSection: section,
    sectionIndex: index,
    totalSections: plan.sections.length
  }
}));

return items;

// Merge writer content and pexels images per section
const writerItems = $('✍️ NODE 2 — Writer AI').all();
const imageItems = $('🎨 NODE 3 — Pexels Images').all();
const planItems = $('📋 Parse Plan').all();

const sections = [];
let paperTitle = '';
let paperAbstract = '';
let topic = '';
let combinerConfig = {};

for (let i = 0; i < planItems.length; i++) {
  const plan = planItems[i].json;
  paperTitle = plan.paperTitle;
  paperAbstract = plan.paperAbstract;
  topic = plan.topic;
  combinerConfig = plan.combiner;

  // Extract writer content
  let sectionContent = '';
  const writerResp = writerItems[i]?.json;
  if (writerResp?.choices?.[0]) {
    sectionContent = writerResp.choices[0].message.content;
  } else if (writerResp?.content?.[0]) {
    sectionContent = writerResp.content[0].text;
  } else if (writerResp?.candidates?.[0]) {
    sectionContent = writerResp.candidates[0].content.parts[0].text;
  }

  // Extract image URL
  let imageUrl = null;
  const imageResp = imageItems[i]?.json;
  if (imageResp?.photos?.[0]?.src?.large) {
    imageUrl = imageResp.photos[0].src.large;
  }

  sections.push({
    title: plan.currentSection.title,
    content: sectionContent,
    imageUrl: imageUrl
  });
}

return [{
  json: {
    paperTitle,
    paperAbstract,
    topic,
    sections,
    combiner: combinerConfig
  }
}];

// Assemble the final research paper output
const mergedData = $('🔀 Merge Results').first().json;
const combinerResp = $input.first().json;

let editorNote = '';
if (combinerResp?.choices?.[0]) {
  editorNote = combinerResp.choices[0].message.content;
} else if (combinerResp?.content?.[0]) {
  editorNote = combinerResp.content[0].text;
} else if (combinerResp?.candidates?.[0]) {
  editorNote = combinerResp.candidates[0].content.parts[0].text;
}

// Build full paper text for easy consumption
let fullPaper = `# ${mergedData.paperTitle}\n\n`;
fullPaper += `## Abstract\n${mergedData.paperAbstract}\n\n`;

for (let i = 0; i < mergedData.sections.length; i++) {
  const s = mergedData.sections[i];
  fullPaper += `## ${i + 1}. ${s.title}\n`;
  if (s.imageUrl) fullPaper += `![${s.title}](${s.imageUrl})\n`;
  fullPaper += `${s.content}\n\n`;
}

fullPaper += `## Editor's Note\n${editorNote}\n`;

return [{
  json: {
    title: mergedData.paperTitle,
    abstract: mergedData.paperAbstract,
    sections: mergedData.sections,
    editorNote: editorNote,
    fullPaperMarkdown: fullPaper,
    metadata: {
      generatedAt: new Date().toISOString(),
      totalSections: mergedData.sections.length,
      topic: mergedData.topic,
      pipeline: 'LLM Arena Research Paper Pipeline'
    }
  }
}];
